"); let b = python_strip(&joined); if b.is_empty() { return; } let title = std::iter::once(name.to_string()).chain(path.iter().cloned()).collect::<Vec<_>>().join(" › "); let mut cur = String::new(); for p in b.split("

") { if !cur.is_empty() && cur.chars().count() + p.chars().count() + 2 > MAX_CHARS { chunks.push((title.clone(), std::mem::take(&mut cur))); } cur = if cur.is_empty() { p.to_string() } else { format!("{cur}

{p}") }; } if !cur.is_empty() { chunks.push((title, cur.chars().take(MAX_CHARS * 2).collect())); } }; for line in text.lines() { let hashes = line.chars().take_while(|c| *c == '#').count(); let rest = line.get(hashes..).unwrap_or(""); let is_heading = (1..=3).contains(&hashes) && rest.starts_with(char::is_whitespace); if is_heading { flush(&path, &body, &mut chunks); body.clear(); path = if hashes > 1 { let mut p: Vec<String> = path.iter().take(hashes.saturating_sub(2)).cloned().collect(); p.push(python_strip(rest).to_string()); p } else { Vec::new() }; } else { body.push(line); } } flush(&path, &body, &mut chunks); chunks }

