"); if warnings.len() > 5 { message.push_str(&format!("

{} additional import warnings.", warnings.len() - 5)); } s.ui_requests.push(crate::UiRequest::Message(message)); } let d = s.doc()?; Ok( json!({"index": i, "title": d.display_title(), "sheets": d.wb.sheets.iter().map(|s| s.name.clone()).collect::<Vec<_>>(), "warnings": warnings}), ) }

